<div class="custom-faq-accordion" aria-label="Frequently Asked Questions"><h2 id="frequently-asked-questions">Frequently Asked Questions</h2><div class="faq-item"><button class="faq-question open" type="button" aria-expanded="true" aria-controls="faq-answer-0"><span class="faq-title"><h3 id="how-much-does-click-to-whatsapp-ads-cost">How much does Click-to-WhatsApp Ads cost?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-0" class="faq-answer open" role="region" aria-hidden="false" style="max-height:none;">There is no fixed cost for Click-to-WhatsApp ads. It mainly depends on your ad quality, target audience, and industry. You generally pay for Meta ad spend and per-conversation charges.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-1"><span class="faq-title"><h3 id="which-campaign-objective-should-i-choose-for-click-to-whatsapp-ads">Which campaign objective should I choose for Click-to-WhatsApp Ads?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-1" class="faq-answer" role="region" aria-hidden="true">An engagement objective is a good choice if your goal is more WhatsApp conversations. Choose "Leads" if you want to collect inquiries and customer details.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-2"><span class="faq-title"><h3 id="which-industries-benefit-most-from-click-to-whatsapp-ads">Which industries benefit most from Click-to-WhatsApp Ads?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-2" class="faq-answer" role="region" aria-hidden="true">Click-to-WhatsApp Ads work best for eCommerce, real estate, healthcare, automotive, and local service businesses that rely on high-intent lead generation and personalized customer consideration.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-3"><span class="faq-title"><h3 id="what-should-i-include-in-my-click-to-whatsapp-ad-message">What should I include in my Click-to-WhatsApp Ad message?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-3" class="faq-answer" role="region" aria-hidden="true">Keep your ad copy, creative, and welcome message consistent with the same offer. Add a clear call-to-action and a few qualifying questions.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-4"><span class="faq-title"><h3 id="do-i-need-the-whatsapp-business-api-for-click-to-whatsapp-ads">Do I need the WhatsApp Business API for Click-to-WhatsApp Ads?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-4" class="faq-answer" role="region" aria-hidden="true">The free WhatsApp Business App works for low-volume campaigns. But to manage higher lead volume and access a shared team inbox or automation, you need to access the WhatsApp API via official providers like HelloBotz.</div></div></div><script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How much does Click-to-WhatsApp Ads cost?","acceptedAnswer":{"@type":"Answer","text":"There is no fixed cost for Click-to-WhatsApp ads. It mainly depends on your ad quality, target audience, and industry. You generally pay for Meta ad spend and per-conversation charges."}},{"@type":"Question","name":"Which campaign objective should I choose for Click-to-WhatsApp Ads?","acceptedAnswer":{"@type":"Answer","text":"An engagement objective is a good choice if your goal is more WhatsApp conversations. Choose \"Leads\" if you want to collect inquiries and customer details."}},{"@type":"Question","name":"Which industries benefit most from Click-to-WhatsApp Ads?","acceptedAnswer":{"@type":"Answer","text":"Click-to-WhatsApp Ads work best for eCommerce, real estate, healthcare, automotive, and local service businesses that rely on high-intent lead generation and personalized customer consideration."}},{"@type":"Question","name":"What should I include in my Click-to-WhatsApp Ad message?","acceptedAnswer":{"@type":"Answer","text":"Keep your ad copy, creative, and welcome message consistent with the same offer. Add a clear call-to-action and a few qualifying questions."}},{"@type":"Question","name":"Do I need the WhatsApp Business API for Click-to-WhatsApp Ads?","acceptedAnswer":{"@type":"Answer","text":"The free WhatsApp Business App works for low-volume campaigns. But to manage higher lead volume and access a shared team inbox or automation, you need to access the WhatsApp API via official providers like HelloBotz."}}]}</script>
    <script>
    (function(){
        if (window.__customFaqAccordionInit) return;
        window.__customFaqAccordionInit = true;

        function closeAnswer(answer, btn) {
            if (!answer) return;
            // if maxHeight is "none", set to current px value to animate to 0
            if (answer.style.maxHeight === "none" || answer.style.maxHeight === "") {
                answer.style.maxHeight = answer.scrollHeight + "px";
            }
            // force reflow
            void answer.offsetHeight;
            answer.style.maxHeight = "0px";
            answer.classList.remove("open");
            if (btn) {
                btn.classList.remove("open");
                btn.setAttribute("aria-expanded", "false");
            }
            answer.setAttribute("aria-hidden", "true");
        }

        function openAnswer(answer, btn) {
            if (!answer) return;
            // set to exact height so transition works
            answer.style.maxHeight = answer.scrollHeight + "px";
            answer.classList.add("open");
            if (btn) {
                btn.classList.add("open");
                btn.setAttribute("aria-expanded", "true");
            }
            answer.setAttribute("aria-hidden", "false");

            // once transition finishes, set to none to allow internal content changes (images) without clipping
            var onTransEnd = function(e){
                if (answer.classList.contains("open")) {
                    answer.style.maxHeight = "none";
                }
                answer.removeEventListener("transitionend", onTransEnd);
            };
            answer.addEventListener("transitionend", onTransEnd);
        }

        document.addEventListener("click", function(e){
            var btn = e.target.closest ? e.target.closest(".custom-faq-accordion .faq-question") : null;
            if (!btn) return;

            var item = btn.closest(".faq-item");
            if (!item) return;
            var answer = item.querySelector(".faq-answer");
            if (!answer) return;

            // if already open, close it
            if (answer.classList.contains("open")) {
                closeAnswer(answer, btn);
            } else {
                // optionally close other open items (uncomment to allow only-one-open)
                var openItems = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
                openItems.forEach(function(o){
                    var parentBtn = o.closest(".faq-item") ? o.closest(".faq-item").querySelector(".faq-question") : null;
                    if (o !== answer) closeAnswer(o, parentBtn);
                });

                openAnswer(answer, btn);
            }
        });

        // Make sure open answers recalc height on window resize (useful if images load or layout changes)
        window.addEventListener("resize", function(){
            var openAnswers = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
            openAnswers.forEach(function(a){
                // if maxHeight is "none", set it to scrollHeight to keep it visible after resize
                if (a.style.maxHeight === "none") {
                    a.style.maxHeight = a.scrollHeight + "px";
                    // then release to none after a tick
                    setTimeout(function(){ a.style.maxHeight = "none"; }, 350);
                }
            });
        });
    })();
    </script>
    
